// Left-wheel diagnostic, revision 1.3
// Arduino Mega: D4 -> STEP, D3 -> DIR, D8 -> EN.
// Required hardware: MS1 disconnected, MS2 -> 5 V/VDD,
// MS3 disconnected. This selects quarter-step mode.
// VDD uses 5 V logic; VMOT uses the separate 12 V motor supply.
// Arduino and A4988 grounds must be connected.
// Disconnect all power before changing wiring.
//
// Serial Monitor: 115200 baud.
// h = enable holding torque without stepping
// r = start the wheel at the selected speed
// s = disable the motor
// The motor stays disabled after setup until h or r is received.

const byte STEP_PIN = 4;
const byte DIR_PIN = 3;
const byte ENABLE_PIN = 8;

// This describes PHYSICAL wiring; it does not configure the MS pins.
// Use 4 with MS2 HIGH and MS1/MS3 LOW (external wires disconnected).
// MS1 currently has a measured low-resistance path to ground; do not tie it HIGH.
const unsigned long MICROSTEPS = 4UL;
const float WHEEL_DIAMETER_CM = 6.0f;
const float TARGET_SPEED_CM_PER_S = 30.0f;
const float START_SPEED_CM_PER_S = 1.0f;
const unsigned long FULL_STEPS_PER_REV = 200UL;
const unsigned int PULSE_WIDTH_US = 5;
const unsigned long RAMP_TIME_US = 3000000UL;

unsigned long finalDelayUs = 0;
unsigned long startDelayUs = 0;
unsigned long currentDelayUs = 0;
unsigned long lastStepUs = 0;
unsigned long rampStartUs = 0;
float startPulseRate = 0.0f;
float finalPulseRate = 0.0f;
bool ramping = false;
bool running = false;

void disableMotor() {
  running = false;
  digitalWrite(STEP_PIN, LOW);
  digitalWrite(ENABLE_PIN, HIGH);
  Serial.println(F("Motor disabled."));
}

void holdMotor() {
  running = false;
  digitalWrite(STEP_PIN, LOW);
  digitalWrite(ENABLE_PIN, LOW);
  Serial.println(F("Holding only: enabled, no step pulses."));
}

void startMotor() {
  running = false;
  digitalWrite(STEP_PIN, LOW);
  digitalWrite(ENABLE_PIN, LOW);
  currentDelayUs = startDelayUs;
  ramping = true;
  Serial.print(F("Running: ramp from "));
  Serial.print(START_SPEED_CM_PER_S);
  Serial.print(F(" to approximately "));
  Serial.print(TARGET_SPEED_CM_PER_S);
  Serial.println(F(" cm/second."));
  lastStepUs = micros();
  rampStartUs = lastStepUs;
  running = true;
}

void setup() {
  digitalWrite(ENABLE_PIN, HIGH);
  pinMode(ENABLE_PIN, OUTPUT);
  digitalWrite(STEP_PIN, LOW);
  pinMode(STEP_PIN, OUTPUT);
  digitalWrite(DIR_PIN, HIGH);
  pinMode(DIR_PIN, OUTPUT);

  const float circumferenceCm = 3.14159265f * WHEEL_DIAMETER_CM;
  finalPulseRate =
    TARGET_SPEED_CM_PER_S * FULL_STEPS_PER_REV * MICROSTEPS
    / circumferenceCm;
  startPulseRate =
    START_SPEED_CM_PER_S * FULL_STEPS_PER_REV * MICROSTEPS
    / circumferenceCm;
  finalDelayUs = (unsigned long)(1000000.0f / finalPulseRate + 0.5f);
  startDelayUs = (unsigned long)(1000000.0f / startPulseRate + 0.5f);
  currentDelayUs = startDelayUs;

  Serial.begin(115200);
  Serial.println(F("Left-wheel diagnostic revision 1.3: quarter stepping"));
  Serial.print(F("Timing assumes microsteps per full step: "));
  Serial.println(MICROSTEPS);
  Serial.print(F("Final pulse interval, microseconds: "));
  Serial.println(finalDelayUs);
  Serial.println(F("Motor disabled. Commands: h=hold, r=run, s=disable."));
}

void loop() {
  if (Serial.available() > 0) {
    switch (Serial.read()) {
      case 'h': case 'H': holdMotor(); break;
      case 'r': case 'R': startMotor(); break;
      case 's': case 'S': disableMotor(); break;
      default: break; // Ignore Serial Monitor line endings.
    }
  }

  if (!running) return;

  const unsigned long nowUs = micros();
  if (nowUs - lastStepUs >= currentDelayUs) {
    lastStepUs = nowUs;
    digitalWrite(STEP_PIN, HIGH);
    delayMicroseconds(PULSE_WIDTH_US);
    digitalWrite(STEP_PIN, LOW);

    // Increase speed linearly with time. Update only after a pulse to keep
    // floating-point work out of the waiting loop.
    if (ramping) {
      const unsigned long elapsedUs = nowUs - rampStartUs;
      if (elapsedUs >= RAMP_TIME_US) {
        currentDelayUs = finalDelayUs;
        ramping = false;
      } else {
        const float progress = (float)elapsedUs / RAMP_TIME_US;
        const float pulseRate = startPulseRate +
          (finalPulseRate - startPulseRate) * progress;
        currentDelayUs = (unsigned long)(1000000.0f / pulseRate + 0.5f);
      }
    }
  }
}
