void loop() {
  if (Serial.available() > 0) {
    switch (Serial.read()) {
      case 'h': case 'H': holdMotor(); break;
      case 'r': case 'R': startMotor(); break;
      case 's': case 'S': disableMotor(); break;
      default: break; // Ignore Serial Monitor line endings.
    }
  }

  if (!running) return;

  const unsigned long nowUs = micros();
  if (nowUs - lastStepUs >= currentDelayUs) {
    lastStepUs = nowUs;
    digitalWrite(STEP_PIN, HIGH);
    delayMicroseconds(PULSE_WIDTH_US);
    digitalWrite(STEP_PIN, LOW);

    // Increase speed linearly with time. Update only after a pulse to keep
    // floating-point work out of the waiting loop.
    if (ramping) {
      const unsigned long elapsedUs = nowUs - rampStartUs;
      if (elapsedUs >= RAMP_TIME_US) {
        currentDelayUs = finalDelayUs;
        ramping = false;
      } else {
        const float progress = (float)elapsedUs / RAMP_TIME_US;
        const float pulseRate = startPulseRate +
          (finalPulseRate - startPulseRate) * progress;
        currentDelayUs = (unsigned long)(1000000.0f / pulseRate + 0.5f);
      }
    }
  }
}

